/** Exact HTML for one-function live serving. Source: sibling HTML file. */
export const PAGE="<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"theme-color\" content=\"#101c1b\"><meta name=\"description\" content=\"An offline, private action desk. Turn one stuck problem into a small action and an editable, exportable artifact. No login, network, or other person needed.\">\n<title>LANTERN 015 · JAR;VIS Connected Solo Desk</title>\n<style>\n:root{color-scheme:dark;--bg:#101c1b;--panel:#172a28;--raised:#203532;--line:#3b5a52;--text:#faf4e5;--muted:#b7c6bc;--sub:#93aca2;--mint:#c5e7c4;--gold:#f2d38e;--red:#f1b39d;--glow:0 16px 55px #0007}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--text);background:radial-gradient(ellipse at 45% -5%,#244d42 0,transparent 47%),radial-gradient(ellipse at 95% 44%,#243632 0,transparent 44%),var(--bg);font:16px/1.55 system-ui,-apple-system,'Segoe UI',sans-serif;min-height:100vh}\nbutton,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.55;cursor:not-allowed}a{color:var(--gold)}:focus-visible{outline:3px solid var(--gold);outline-offset:3px}\n.wrap{max-width:1130px;margin:auto;padding:0 22px 82px}.topbar{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #436158;padding:20px 0 15px;gap:12px}.brand{display:flex;gap:11px;align-items:center;text-transform:uppercase;letter-spacing:.15em;font-size:.77rem;font-weight:800}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border-radius:12px;background:#f2d38e;color:#1b2e27;font-size:23px}.status{border:1px solid #4b715e;background:#193629;color:#ccebc9;border-radius:999px;padding:5px 12px;font-size:.77rem;font-weight:700;white-space:nowrap}\n.hero{display:grid;grid-template-columns:1.2fr .65fr;gap:30px;align-items:end;padding:45px 0 35px}.eyebrow{letter-spacing:.2em;text-transform:uppercase;color:var(--gold);font-size:.74rem;font-weight:800}.hero h1{font-family:Georgia,'Times New Roman',serif;font-weight:normal;line-height:1.06;letter-spacing:-.043em;font-size:clamp(3rem,8vw,5.3rem);margin:11px 0 13px}.hero h1 em{color:var(--mint);font-weight:normal}.intro{font-size:1.06rem;max-width:580px;color:var(--muted);margin:0}.side-quote{border-left:2px solid var(--gold);padding:8px 0 8px 17px;font-family:Georgia,serif;color:#e7ddc1;font-size:1.2rem;line-height:1.45}.side-quote small{display:block;font-family:system-ui;color:var(--sub);font-size:.75rem;margin-top:9px;text-transform:uppercase;letter-spacing:.12em}\n.panel{border:1px solid var(--line);border-radius:20px;background:linear-gradient(150deg,#1c332f,#142522);box-shadow:var(--glow);padding:26px}.headrow{display:flex;gap:10px;align-items:center;justify-content:space-between;margin-bottom:13px;flex-wrap:wrap}.h-label{color:var(--gold);font-size:.71rem;text-transform:uppercase;letter-spacing:.17em;font-weight:800}.h-title{font-family:Georgia,serif;font-size:1.8rem;font-weight:normal;margin:0 0 5px}.hint{color:var(--muted);font-size:.91rem;margin:0 0 20px}.grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.98fr);gap:20px}.modes{display:grid;grid-template-columns:1fr 1fr;gap:10px}.mode{background:#223b35;border:1px solid #49665b;color:var(--text);border-radius:14px;padding:15px;text-align:left;transition:transform .15s,border-color .15s,background .15s;min-height:99px}.mode:hover{background:#2b4a41;transform:translateY(-1px)}.mode[aria-pressed=true]{border:2px solid var(--gold);padding:14px;background:#394637}.mode strong{display:block;font-size:1rem;margin:1px 0}.mode span{display:block;font-size:.79rem;color:#c8d4cc}.mode-icon{color:var(--gold);font-size:1.16rem}\n.field{margin-top:17px}label{display:block;font-size:.87rem;color:#e1e8dc;font-weight:700;margin-bottom:7px}textarea,input,select{background:#102220;border:1px solid #4b6b5f;border-radius:11px;color:var(--text);padding:12px 14px;width:100%;min-width:0}textarea{resize:vertical;min-height:108px;line-height:1.5}input::placeholder,textarea::placeholder{color:#9daea6}input[type=range]{padding:0;accent-color:var(--gold)}.two{display:grid;grid-template-columns:1fr 1fr;gap:13px}.options-row{display:flex;gap:8px;flex-wrap:wrap}.pill{border-radius:999px;padding:9px 13px;background:#223b35;border:1px solid #547465;color:#e9eee5;font-size:.83rem}.pill[aria-pressed=true]{background:var(--gold);border-color:var(--gold);color:#14221c;font-weight:800}.primary{background:var(--gold);border:1px solid var(--gold);color:#17291e;font-weight:850;border-radius:12px;padding:13px 17px;box-shadow:0 5px 0 #a8874d;transition:transform .1s}.primary:hover{transform:translateY(-1px)}.primary:active{transform:translateY(3px);box-shadow:0 2px 0 #a8874d}.secondary{background:#29453f;color:var(--text);border:1px solid #618174;border-radius:11px;padding:11px 14px;font-weight:650}.secondary:hover{background:#33534b}.danger{border-color:#a47166;color:#ffd6c6}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:18px}.caption{color:#94ada2;font-size:.8rem}.fine{font-size:.79rem;color:var(--sub)}.banner{margin-top:16px;padding:12px 14px;border:1px solid #50786b;border-radius:12px;background:#1b3b32;color:#e4f1dc;font-size:.86rem}.error{background:#4d2927;border-color:#b56e62;color:#ffe0d8}\n.output-card{background:#12231f;border:1px solid #3e6658;border-radius:15px;padding:22px;min-height:275px}.output-card .step{display:flex;justify-content:space-between;gap:10px;align-items:center}.tag{color:#1d352a;background:var(--mint);padding:4px 9px;border-radius:6px;font-weight:800;font-size:.7rem;letter-spacing:.03em;text-transform:uppercase}.mini{font-size:.78rem;color:var(--sub);text-transform:uppercase;letter-spacing:.1em}.focus{font-family:Georgia,serif;font-size:clamp(1.5rem,3vw,2.15rem);line-height:1.22;margin:20px 0 10px}.detail{white-space:pre-wrap;color:#d3dfd2;font-size:.94rem}.rule{height:1px;background:#36584a;margin:18px 0}.criteria{font-weight:750;color:var(--gold)}.empty{display:grid;align-content:center;justify-items:center;text-align:center;gap:8px;min-height:255px;color:var(--muted)}.empty-icon{font-size:2rem;color:var(--gold)}.empty p{margin:0;max-width:310px}.receipt{margin-top:17px}.receipt textarea{min-height:88px}.draft-label{display:flex;align-items:center;justify-content:space-between;gap:10px}.small-btn{padding:7px 11px;border-radius:8px;font-size:.77rem;color:var(--text);background:#274238;border:1px solid #5a7e69}.checkline{display:flex;align-items:center;gap:10px;margin:13px 0;padding:12px;background:#1a3730;border:1px solid #537265;border-radius:10px;color:#e4eddd;font-weight:700}.checkline input{width:20px;height:20px;accent-color:var(--gold)}.checkline label{margin:0}.output-tools{display:flex;gap:7px;flex-wrap:wrap;margin-top:16px}.timeline{border-top:1px solid #3d6559;margin-top:16px;padding-top:15px}.timeline-card{border:1px solid #38594d;background:#182e28;border-radius:12px;padding:14px;margin-bottom:9px}.timeline-card b{display:block}.timeline-meta{color:#a3bbad;font-size:.76rem}.timeline-body{color:#cbd8cd;font-size:.85rem;margin:4px 0 0}.footer{margin-top:36px;border-top:1px solid #446456;padding:18px 0;color:#a9c1b2;font-size:.83rem;display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap}details{margin-top:15px;border-top:1px solid #3d594e;padding-top:14px}summary{cursor:pointer;color:var(--mint);font-weight:700}details p{color:var(--muted);font-size:.85rem}.jarvis-panel{margin-top:23px;border-color:#58785f;background:linear-gradient(140deg,#213e35,#122722)}.jarvis-panel .jarvis-intro{max-width:860px;color:var(--muted);margin:0 0 15px}.offer-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.offer{border:1px solid #527667;border-radius:14px;background:#172e28;padding:16px;display:flex;flex-direction:column;gap:9px}.offer strong{font-size:1.04rem;color:var(--mint)}.offer p{font-size:.88rem;line-height:1.4;color:var(--muted);margin:0;flex:1}.offer .secondary{width:100%;text-align:left}.availability{color:#dceecb;font-size:.71rem;font-weight:800;letter-spacing:.12em}.jarvis-response{margin-top:15px;padding:15px;border:1px solid #64836e;border-radius:11px;background:#0d2420;color:#e5eeda;white-space:pre-wrap;font-size:.88rem}.jarvis-disclosure{border-left:2px solid #a4b69f;padding:8px 12px;font-size:.83rem;color:var(--muted);margin:16px 0 0}#library{margin-top:23px}.library-head{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px}.library-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(225px,1fr));gap:11px;margin-top:13px}.library-item{border:1px solid #456858;background:#1d332f;border-radius:13px;padding:15px;text-align:left;color:var(--text);min-height:125px}.library-item:hover{border-color:var(--gold)}.library-item strong{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin:6px 0}.library-item .muted{font-size:.78rem;color:var(--sub)}.hidden{display:none!important}.sr-only{position:absolute;left:-10000px;top:auto;width:1px;height:1px;overflow:hidden}.print-only{display:none}\n@media(max-width:790px){.hero{grid-template-columns:1fr;padding-top:28px;gap:20px}.grid{grid-template-columns:1fr}.panel{padding:20px}.side-quote{font-size:1.04rem}.hero h1{font-size:3.4rem}}@media(max-width:650px){.offer-list{grid-template-columns:1fr}}@media(max-width:430px){.wrap{padding:0 13px 45px}.topbar{padding:13px 0}.brand{letter-spacing:.06em}.status{font-size:.67rem;padding:4px 8px}.panel{padding:16px;border-radius:15px}.modes{gap:8px}.mode{padding:12px;min-height:105px}.mode[aria-pressed=true]{padding:11px}.mode strong{font-size:.9rem}.two{grid-template-columns:1fr}.focus{font-size:1.55rem}}\n@media print{body{background:white;color:#141d16}.topbar,.hero,.form-panel,.output-tools,.footer,#library,.no-print{display:none!important}.grid{display:block}.output-panel{border:0;box-shadow:none;background:white;color:black;padding:0}.output-card{border:0;background:white;color:black}.focus,.detail,label,.criteria{color:black}.print-only{display:block}.receipt textarea{border:1px solid #777;color:black;background:white}.draft-label{color:black}}\n.jarvis-panel h3{margin:20px 0 10px;color:#edd9a8}.jarvis-panel textarea{width:100%;min-height:74px}.jarvis-panel button:disabled{opacity:.5;cursor:not-allowed}.jarvis-panel #connected-offers{margin-top:14px}.jarvis-panel #connected-result{margin:13px 0}.jarvis-panel button{margin:3px 0}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n<header class=\"topbar\"><div class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">✳</span><span>LANTERN <strong>014</strong> / SOLO DESK</span></div><span class=\"status\">● PRIVATE · OFFLINE · YOURS</span></header>\n<section class=\"hero\"><div><div class=\"eyebrow\">Small useful things, finished</div><h1>Make one thing <em>happen.</em></h1><p class=\"intro\">Bring a problem, an idea, or a stuck decision. Leave with one doable move and a working document. No account. No collaborators. No perfect plan required.</p></div><div class=\"side-quote\">“A useful step ends somewhere different from where it began.”<small>Solo Desk · local-first workshop</small></div></section>\n<main class=\"grid\">\n<section class=\"panel form-panel\" aria-labelledby=\"start-title\"><div class=\"headrow\"><span class=\"h-label\">01 / Choose a lane</span><span class=\"caption\">2 minutes to start</span></div><h2 class=\"h-title\" id=\"start-title\">What are we doing?</h2><p class=\"hint\">Choose what will help you make progress today. These are practical templates, not an AI pretending to understand your situation.</p>\n<div class=\"modes\" role=\"group\" aria-label=\"Choose the kind of progress\">\n<button class=\"mode\" type=\"button\" data-mode=\"untangle\" aria-pressed=\"true\"><span class=\"mode-icon\" aria-hidden=\"true\">✦</span><strong>Untangle</strong><span>Find the next move when everything feels tangled.</span></button>\n<button class=\"mode\" type=\"button\" data-mode=\"make\" aria-pressed=\"false\"><span class=\"mode-icon\" aria-hidden=\"true\">◇</span><strong>Make</strong><span>Turn an idea into a real first draft.</span></button>\n<button class=\"mode\" type=\"button\" data-mode=\"decide\" aria-pressed=\"false\"><span class=\"mode-icon\" aria-hidden=\"true\">⇄</span><strong>Decide</strong><span>Compare two choices without getting trapped.</span></button>\n<button class=\"mode\" type=\"button\" data-mode=\"debug\" aria-pressed=\"false\"><span class=\"mode-icon\" aria-hidden=\"true\">⌁</span><strong>Test</strong><span>Investigate what's broken with a reversible test.</span></button>\n</div>\n<div class=\"field\"><label id=\"problem-label\" for=\"problem\">What's taking up space in your head?</label><textarea id=\"problem\" maxlength=\"1400\" placeholder=\"Example: I have hundreds of photos and don't know where to begin.\"></textarea></div>\n<div class=\"two\"><div class=\"field\"><label id=\"finish-label\" for=\"finish\">What's one useful outcome?</label><input id=\"finish\" maxlength=\"240\" placeholder=\"Example: find my first 10 favorites\"></div><div class=\"field\"><label id=\"limit-label\" for=\"limit\">What's the main constraint?</label><input id=\"limit\" maxlength=\"240\" placeholder=\"Example: only my old laptop\"></div></div>\n<div class=\"field\"><label>How much time can you give it?</label><div class=\"options-row\" role=\"group\" aria-label=\"Available time\"><button class=\"pill\" type=\"button\" data-min=\"5\" aria-pressed=\"false\">5 min</button><button class=\"pill\" type=\"button\" data-min=\"10\" aria-pressed=\"true\">10 min</button><button class=\"pill\" type=\"button\" data-min=\"20\" aria-pressed=\"false\">20 min</button><button class=\"pill\" type=\"button\" data-min=\"40\" aria-pressed=\"false\">40 min</button></div></div>\n<div class=\"actions\"><button class=\"primary\" type=\"button\" id=\"build\">Build my next move →</button><button class=\"secondary\" type=\"button\" id=\"quick\">I just need a 5-minute start</button></div>\n<p class=\"fine\" style=\"margin:15px 0 0\">Your notes are held only in this open tab, not persisted in browser storage. Export a backup. No private notes are sent to JAR;VIS; only a separately approved short offer can cross the remote boundary.</p>\n<details><summary>What can this tool actually do?</summary><p>It creates a tailored starting plan and an editable working note. You decide what to do, record whether it worked, and can save a new immutable local snapshot or fork your plan. It does not search online, contact people, analyze private files, or guarantee that a step will succeed.</p></details>\n</section>\n<section class=\"panel output-panel\" aria-labelledby=\"output-title\"><div class=\"headrow\"><span class=\"h-label\">02 / Produce something</span><span class=\"caption\" id=\"current-version\">Nothing active yet</span></div><h2 class=\"h-title\" id=\"output-title\">Your next move</h2><p class=\"hint\">One action, one clear finish line, one artifact you can keep.</p>\n<div id=\"empty\" class=\"empty output-card\"><span class=\"empty-icon\" aria-hidden=\"true\">✧</span><strong>Your useful step goes here.</strong><p>Describe what you're working on—or tap the five-minute start to get moving.</p></div>\n<div id=\"result\" class=\"hidden\"><div class=\"output-card\"><div class=\"step\"><span class=\"tag\" id=\"mode-tag\">Untangle</span><span class=\"mini\" id=\"duration\">10-minute action</span></div><h3 class=\"focus\" id=\"action-title\"></h3><p class=\"detail\" id=\"action-body\"></p><div class=\"rule\"></div><div class=\"mini\">The finish line</div><p class=\"criteria\" id=\"finish-line\"></p></div>\n<div class=\"receipt\"><div class=\"draft-label\"><label for=\"working-note\">Editable working note · your actual output</label><span class=\"caption\">Autosaves locally</span></div><textarea id=\"working-note\" rows=\"9\" maxlength=\"12000\" spellcheck=\"true\"></textarea><label class=\"checkline\" for=\"completed\"><input id=\"completed\" type=\"checkbox\"> I actually completed the step</label><label for=\"evidence\">What changed? (Leave blank if nothing changed.)</label><textarea id=\"evidence\" rows=\"3\" maxlength=\"1500\" placeholder=\"Example: Found 10 photos; copied 3 favorites into a new folder. Or: the test failed because…\"></textarea><div class=\"output-tools\"><button class=\"secondary\" type=\"button\" id=\"save\">Save snapshot</button><button class=\"secondary\" type=\"button\" id=\"fork\">Fork another approach</button><button class=\"secondary\" type=\"button\" id=\"copy\">Copy note</button><button class=\"secondary\" type=\"button\" id=\"download\">Download .txt</button><button class=\"secondary\" type=\"button\" id=\"print\">Print</button></div><p class=\"fine\" id=\"save-status\">This is a draft until you record what actually happened.</p></div></div>\n</section></main>\n<section id=\"jarvis\" class=\"panel jarvis-panel\" aria-labelledby=\"jarvis-title\">\n<div class=\"headrow\"><span class=\"h-label\">03 / JAR;VIS · executable offers</span><span class=\"status\" id=\"jarvis-availability\">● OFFLINE TOOLS READY</span></div>\n<h2 class=\"h-title\" id=\"jarvis-title\">Here's what I can actually do.</h2>\n<p class=\"jarvis-intro\">Not another invitation to make an invitation. These buttons run local actions and produce a changed note, a downloadable file, or a concrete diagnostic report. No model, server, account, or additional person is involved.</p>\n<p class=\"hint\" id=\"jarvis-context\">Create a working step above and I'll identify the most useful action I can execute here.</p>\n<div class=\"offer-list\">\n<div class=\"offer\"><span class=\"availability\">AVAILABLE NOW · MODIFIES YOUR NOTE</span><strong>Make a usable checklist</strong><p>I will put a task-specific, editable checklist directly into the current working note—not just advise you to make one.</p><button class=\"secondary\" type=\"button\" id=\"jarvis-checklist\">JAR;VIS, build my checklist →</button></div>\n<div class=\"offer\"><span class=\"availability\">AVAILABLE NOW · CREATES CSV</span><strong>Generate a progress tracker</strong><p>I can download a real spreadsheet-friendly CSV with task rows, a status column, and room for evidence. I can't change your computer's existing files.</p><button class=\"secondary\" type=\"button\" id=\"jarvis-tracker\">JAR;VIS, make the tracker →</button></div>\n<div class=\"offer\"><span class=\"availability\">AVAILABLE NOW · CREATES HTML</span><strong>Build a portable work page</strong><p>I can generate another standalone HTML file containing your goal, instructions, live checkboxes, a notes area, and a print button.</p><button class=\"secondary\" type=\"button\" id=\"jarvis-page\">JAR;VIS, build the page →</button></div>\n<div class=\"offer\"><span class=\"availability\">AVAILABLE NOW · CHECKS DRAFT</span><strong>Audit this work product</strong><p>I can flag missing outcomes, unchanged template fields, and unsupported completion claims. I cannot verify that an external task happened.</p><button class=\"secondary\" type=\"button\" id=\"jarvis-audit\">JAR;VIS, inspect what we have →</button></div>\n</div>\n<div id=\"jarvis-response\" class=\"jarvis-response hidden\" role=\"status\" aria-live=\"polite\"></div>\n<p class=\"jarvis-disclosure\"><strong>Not available inside this offline copy:</strong> reading your photographs or folders, browsing the internet, sending messages, changing GitHub repositories, running arbitrary programs, or claiming an outside task is complete. Those would require separate connected tools and your authorization. The buttons above genuinely run here.</p>\n</section>\n\n<section id=\"connected\" class=\"panel jarvis-panel\" aria-labelledby=\"connected-title\">\n <div class=\"headrow\"><span class=\"h-label\">03b / JAR;VIS · live connected tools</span><span class=\"status\" id=\"connected-state\">NOT CONNECTED</span></div>\n <h2 class=\"h-title\" id=\"connected-title\">Ask the real machinery what it can do.</h2>\n <p class=\"hint\">Verify actual GitHub source hashes for JAR;VIS, GHoT, STATIC OS and reLATTE. The remote endpoint can read public sources and compile downloadable evidence, but has <strong>no permission to change GitHub</strong>.</p>\n <button id=\"connect-sources\" type=\"button\" class=\"primary\">Connect and verify live sources →</button>\n <p id=\"connected-result\" class=\"hint\" role=\"status\" aria-live=\"polite\">No request sent yet.</p>\n <div id=\"connected-offers\" class=\"offer-list\" aria-live=\"polite\"></div>\n <hr style=\"margin:22px 0;border:0;border-top:1px solid #537265\">\n <h3>Run the actual source-owned JAR;VIS live-offer router</h3>\n <label for=\"connected-offer-text\">One short offer (4–240 characters)</label>\n <textarea id=\"connected-offer-text\" rows=\"3\" maxlength=\"240\" placeholder=\"I can play guitar for 15 minutes right now\"></textarea>\n <label style=\"display:flex;gap:10px;align-items:flex-start;margin:13px 0\"><input id=\"connected-consent\" type=\"checkbox\" style=\"width:21px;height:21px;flex:none\"><span>I authorize sending <strong>only this short offer</strong> to the remote JAR;VIS router. No work notes, shelf, photos or other files will be submitted.</span></label>\n <button id=\"connected-route\" type=\"button\" class=\"secondary\">Execute real routing engine →</button>\n <p id=\"connected-route-result\" class=\"jarvis-response hidden\" aria-live=\"polite\"></p>\n <button id=\"connected-receipt\" type=\"button\" class=\"small-btn hidden\">Download source-owned routing receipt</button>\n <hr style=\"margin:22px 0;border:0;border-top:1px solid #537265\">\n <h3>Do something real now: record audio</h3>\n <p class=\"hint\">Microphone access is requested only if you press Start. Recording happens entirely on your device and downloads an audio file; it is never uploaded to this backend.</p>\n <button id=\"audio-start\" type=\"button\" class=\"secondary\">Start local recording</button>\n <button id=\"audio-stop\" type=\"button\" class=\"small-btn\" disabled>Stop & download actual audio</button>\n <p id=\"audio-status\" class=\"hint\" aria-live=\"polite\">Microphone idle.</p>\n <p class=\"jarvis-disclosure\">The remote router produces a <strong>proposal only</strong>, never a claim that an action occurred. The source inspector really reads current GitHub files; the microphone recorder really makes a local file. No sign-in, Vercel, database writes or cloud model required.</p>\n</section>\n<section id=\"library\" class=\"panel\" aria-labelledby=\"library-title\"><div class=\"library-head\"><div><div class=\"h-label\">04 / This-tab history</div><h2 class=\"h-title\" id=\"library-title\">This-tab Work Shelf</h2><p class=\"hint\" style=\"margin-bottom:0\">Copies preserve your earlier notes. An outcome is only marked complete when you say so.</p></div><div class=\"actions\"><button class=\"secondary\" type=\"button\" id=\"export-shelf\">Export shelf .json</button><button class=\"secondary\" type=\"button\" id=\"import-shelf\">Import shelf .json</button><input id=\"import-file\" type=\"file\" accept=\"application/json,.json\" class=\"sr-only\"><button class=\"secondary danger\" type=\"button\" id=\"clear-shelf\">Clear local shelf</button></div></div><div id=\"library-list\" class=\"library-list\"></div><p class=\"fine\">Live privacy mode: this tab holds your notes in volatile memory. Refreshing or closing it erases them. Export to keep your work. Only the explicit short-offer route sends text to the backend.</p></section>\n<div id=\"notice\" role=\"status\" aria-live=\"polite\" class=\"banner hidden\"></div>\n<footer class=\"footer\"><span>✳ LANTERN 014 · Solo Desk · offline working tool</span><span>Evidence ≠ intention · A draft ≠ a completed action · A copied plan ≠ a real-world event</span></footer></div>\n<script>\n'use strict';\n(()=>{\nconst KEY='lantern015_volatile_work_shelf',MAX=60;const sessionStore=new Map();\nconst $=x=>document.getElementById(x);\nconst el={problem:$('problem'),finish:$('finish'),limit:$('limit'),note:$('working-note'),evidence:$('evidence'),completed:$('completed'),result:$('result'),empty:$('empty'),notice:$('notice'),library:$('library-list')};\nconst labels={untangle:'Untangle',make:'Make',decide:'Decide',debug:'Test'};\nconst prefix={untangle:'Sort out',make:'Draft',decide:'Compare',debug:'Check'};\nlet mode='untangle',minutes=10,active=null,shelf=[],storageAvailable=true,autosaveTimer=0;\nfunction uid(){return (globalThis.crypto&&crypto.randomUUID)?crypto.randomUUID():`local-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;}\nfunction safe(t,n=1500){return String(t??'').replace(/[\\u0000-\\u0008\\u000B\\u000C\\u000E-\\u001F]/g,' ').trim().slice(0,n);}\nfunction when(){return new Date().toISOString();}\nfunction fmt(iso){try{return new Date(iso).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});}catch{return iso;}}\nfunction notice(msg,isError=false){el.notice.textContent=msg;el.notice.classList.remove('hidden');el.notice.classList.toggle('error',isError);clearTimeout(notice.timer);notice.timer=setTimeout(()=>el.notice.classList.add('hidden'),6500);}\nfunction persist(){try{sessionStore.set(KEY,JSON.stringify({schema:'lantern.solo-shelf/v1',shelf,active}));storageAvailable=false;}catch(e){storageAvailable=false;notice('Local storage is unavailable or full. Export your work using Download / Export shelf.',true);}}\nfunction load(){try{const saved=JSON.parse(sessionStore.get(KEY)||'null');if(saved&&saved.schema==='lantern.solo-shelf/v1'){shelf=Array.isArray(saved.shelf)?saved.shelf.filter(valid).slice(0,MAX):[];active=valid(saved.active)?saved.active:null;}}catch{notice('Saved data could not be read. Starting with a fresh local shelf.',true);}}\nfunction valid(s){return !!s&&typeof s==='object'&&!Array.isArray(s)&&typeof s.id==='string'&&s.id.length<110&&Object.hasOwn(labels,s.mode)&&typeof s.problem==='string'&&s.problem.length<=1400&&typeof s.note==='string'&&s.note.length<=12000&&typeof s.time==='number'&&[5,10,20,40].includes(s.time)&&typeof s.action==='string'&&s.action.length<=450&&typeof s.finishLine==='string'&&s.finishLine.length<=500&&typeof s.created==='string'&&s.created.length<55&&(!s.parent||typeof s.parent==='string'&&s.parent.length<110)&&typeof s.evidence==='string'&&s.evidence.length<=1500&&typeof s.completed==='boolean';}\nfunction cleanProject(s){return {id:s.id,parent:s.parent||null,mode:s.mode,problem:s.problem,finish:s.finish||'',limit:s.limit||'',time:s.time,action:s.action,actionBody:s.actionBody||'',finishLine:s.finishLine,note:s.note,evidence:s.evidence,completed:s.completed,created:s.created,updated:s.updated||s.created};}\nfunction build(mode,problem,finish,limit,min){\n const topic=problem||'the thing you want to move forward'; const target=finish||'one visible change';const constraint=limit||'the time and materials you already have';\n const first=topic.replace(/[\\s.?!]+$/,'');\n const short=first.length>88?first.slice(0,85)+'…':first;\n if(mode==='untangle')return {action:'Make three piles: known, unknown, next',body:`Put “${short}” at the top of a page. Write only facts you can verify under KNOWN, open questions under UNKNOWN, and actions you can do yourself under NEXT. Choose the smallest item in NEXT that fits ${min} minutes.`,line:`A page exists with those three headings and one specific action circled. Desired outcome: ${target}.`,note:`WORKING MAP\\n\\nProblem: ${topic}\\nOutcome I want: ${target}\\nConstraint: ${constraint}\\n\\nKNOWN (facts, not guesses)\\n- \\n\\nUNKNOWN (questions to investigate)\\n- \\n\\nNEXT (actions I can do alone)\\n1. \\n\\nOne step to do in ${min} minutes:\\n\\nWhat I actually observed:\\n`};\n if(mode==='make')return {action:'Create the rough first version',body:`Start an actual draft for “${short}” in the working note below. Fill the title, who/what it serves, three useful parts, and the next edit. Do not spend the first ${min} minutes making it polished.`,line:`A saved first draft exists. Target output: ${target}. Constraint to respect: ${constraint}.`,note:`FIRST DRAFT\\n\\nWorking title: ${topic}\\nIntended outcome: ${target}\\nConstraint: ${constraint}\\n\\nWhat this is / what it does:\\n\\nPart 1 — start:\\n\\nPart 2 — useful middle:\\n\\nPart 3 — concrete ending:\\n\\nSmallest improvement for the next version:\\n`};\n if(mode==='decide')return {action:'Run a reversible two-option comparison',body:`Name two things you could actually do about “${short}.” Compare each against the same three measures: time today, possible downside, and whether you can reverse it. Choose the least costly test—not a lifetime commitment.`,line:`Two real options are written down and one ${min}-minute trial is selected. Desired outcome: ${target}. The decision remains yours.`,note:`DECISION CARD\\n\\nQuestion: ${topic}\\nDesired result: ${target}\\nConstraint: ${constraint}\\n\\nOption A:\\n- First action:\\n- Cost / time:\\n- Downside:\\n- Reversible?\\n\\nOption B:\\n- First action:\\n- Cost / time:\\n- Downside:\\n- Reversible?\\n\\nSmall test I choose (not a permanent commitment):\\n\\nWhat would change my mind?\\n`};\n return {action:'Record what is happening; test one cause',body:`Describe the exact failure involving “${short}.” Write EXPECTED versus OBSERVED. Change only one reversible thing that you can test in ${min} minutes. Record the result, including failures.`,line:`One test has a reproducible step, an observed result, and a way to undo it. Outcome sought: ${target}.`,note:`BUG / PROBLEM RECEIPT\\n\\nProblem: ${topic}\\nExpected behavior:\\nObserved behavior:\\nWhen and where it happens:\\n\\nCurrent constraint: ${constraint}\\n\\nSmallest reversible test (${min} min):\\n1. \\n\\nResult (what actually happened):\\n\\nUndo / restore instructions:\\n\\nNext hypothesis (only if needed):\\n`};\n}\nfunction newProject(quick=false){const problem=safe(el.problem.value,1400),finish=safe(el.finish.value,240),limit=safe(el.limit.value,240);if(!problem&&!quick){el.problem.focus();notice('Write one sentence about what you want to move forward.',true);return;}\n const p=problem||'I need one simple thing to feel less stuck';const use=quick?5:minutes;const data=build(mode,p,finish,limit,use);const now=when();active={id:uid(),parent:null,mode,problem:p,finish,limit,time:use,action:data.action,actionBody:data.body,finishLine:data.line,note:data.note,evidence:'',completed:false,created:now,updated:now};persist();renderActive();offerContext();notice('Created a first working step. Edit the note; save a snapshot when you have something to keep.');}\nfunction flush(){if(!active)return;active.note=safe(el.note.value,12000);active.evidence=safe(el.evidence.value,1500);active.completed=!!el.completed.checked;active.updated=when();persist();}\nfunction renderActive(){const exists=!!active;el.result.classList.toggle('hidden',!exists);el.empty.classList.toggle('hidden',exists);if(!exists){$('current-version').textContent='Nothing active yet';return;}\n $('current-version').textContent='Working copy · '+active.id.slice(-7);$('mode-tag').textContent=labels[active.mode];$('duration').textContent=`${active.time}-minute action`;$('action-title').textContent=active.action;$('action-body').textContent=active.actionBody;$('finish-line').textContent=active.finishLine;el.note.value=active.note;el.evidence.value=active.evidence;el.completed.checked=active.completed;\n $('save-status').textContent=active.completed?'Marked complete by you. Save a snapshot to preserve this outcome.':'Working draft. Completion is not assumed; record what changed.';\n}\nfunction save(){if(!active){notice('Create a next move first.',true);return;}flush();const snapshot=cleanProject({...active,id:uid(),parent:active.parent||null,updated:when()});if(shelf.length>=MAX){notice('Shelf full (60 snapshots). Export it, then clear the shelf to make room.',true);return;}\n shelf.unshift(snapshot);persist();renderShelf();notice('Snapshot saved. Your earlier entries remain unchanged.');}\nfunction fork(){if(!active){notice('Create a next move first.',true);return;}flush();const parent=active.id;const now=when();active={...cleanProject(active),id:uid(),parent,completed:false,evidence:'',created:now,updated:now};persist();renderActive();offerContext();notice('Fork created. The earlier working copy was not overwritten; save it first if you want to keep it.');}\nfunction restore(s){active={...cleanProject(s),id:uid(),parent:s.id,completed:false,evidence:'',created:when(),updated:when()};mode=active.mode;minutes=active.time;el.problem.value=active.problem;el.finish.value=active.finish;el.limit.value=active.limit;applyMode();applyMinutes();persist();renderActive();offerContext();window.scrollTo({top:0,behavior:'smooth'});notice('A new editable copy opened. The shelf snapshot was not modified.');}\nfunction applyMode(){document.querySelectorAll('[data-mode]').forEach(btn=>btn.setAttribute('aria-pressed',String(btn.dataset.mode===mode)));const text={untangle:['What’s taking up space in your head?','What’s one useful outcome?'],make:['What do you want to make?','What would a first usable draft do?'],decide:['What decision is stuck?','What matters most in the decision?'],debug:['What isn’t working?','What would success look like?']}[mode];$('problem-label').textContent=text[0];$('finish-label').textContent=text[1];}\nfunction applyMinutes(){document.querySelectorAll('[data-min]').forEach(btn=>btn.setAttribute('aria-pressed',String(+btn.dataset.min===minutes)));}\nfunction simpleFile(name,body,mime){const blob=new Blob([body],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}\nfunction plain(s){const lines=['LANTERN 014 · SOLO DESK','-----------------------',`Mode: ${labels[s.mode]}`,`Created: ${fmt(s.created)}`,'',`PROBLEM\\n${s.problem}`,'',`NEXT MOVE\\n${s.action}`,'',s.actionBody,'',`FINISH LINE\\n${s.finishLine}`,'',`WORKING NOTE\\n${s.note}`,'',`COMPLETION: ${s.completed?'Self-reported completed':'Not yet reported complete'}`,`WHAT CHANGED\\n${s.evidence||'(not recorded)'}`,'',`Local ID: ${s.id}`,`Parent copy: ${s.parent||'none'}`,'','These notes record your own observations. The software cannot independently verify real-world completion.'];return lines.join('\\n');}\nfunction renderShelf(){el.library.replaceChildren();if(!shelf.length){const d=document.createElement('div');d.className='timeline-card';d.textContent='No saved snapshots yet. Create a plan, edit your note, then use Save snapshot.';el.library.append(d);return;}\n shelf.forEach(s=>{const b=document.createElement('button');b.type='button';b.className='library-item';const cap=document.createElement('span');cap.className='mini';cap.textContent=labels[s.mode]+(s.completed?' · self-reported done':' · working');const title=document.createElement('strong');title.textContent=s.problem.slice(0,90);const info=document.createElement('span');info.className='muted';info.textContent=`${fmt(s.updated)} · ${s.parent?'forked copy':'original'}`;const foot=document.createElement('span');foot.className='muted';foot.textContent='Open as editable copy →';foot.style.display='block';foot.style.marginTop='9px';b.append(cap,title,info,foot);b.addEventListener('click',()=>restore(s));el.library.append(b);});}\nfunction exportShelf(){flush();simpleFile('Lantern_014_Solo_Desk_Shelf.json',JSON.stringify({schema:'lantern.solo-shelf/v1',exported:when(),shelf,active},null,2),'application/json');notice('Exported a local backup. Keep the file somewhere safe.');}\nasync function importShelf(file){if(!file)return;try{if(file.size>2_000_000)throw Error('File is too large.');const payload=JSON.parse(await file.text());if(payload.schema!=='lantern.solo-shelf/v1'||!Array.isArray(payload.shelf)||payload.shelf.length>MAX||!payload.shelf.every(valid)||payload.active&&!valid(payload.active))throw Error('This is not a valid Solo Desk shelf.');const ids=payload.shelf.map(x=>x.id);if(new Set(ids).size!==ids.length)throw Error('Duplicate snapshot IDs in file.');if(!confirm(`Import ${payload.shelf.length} snapshots? This replaces the current local shelf. Export a backup first if you need it.`))return;shelf=payload.shelf.map(cleanProject);active=payload.active?cleanProject(payload.active):null;persist();renderActive();renderShelf();notice('Imported local shelf from your file. No network used.');}catch(e){notice(`Import refused: ${e.message}`,true);}finally{$('import-file').value='';}}\n\n/* JAR;VIS offer registry. Every declared AVAILABLE_NOW entry maps to a real\n * deterministic local executor; no imaginary network or cloud actions. */\nconst JARVIS_OFFERS=Object.freeze([\n {id:'checklist',effect:'EDIT_CURRENT_NOTE',label:'Create an editable checklist'},\n {id:'tracker',effect:'DOWNLOAD_CSV',label:'Create a structured work tracker'},\n {id:'page',effect:'DOWNLOAD_HTML',label:'Create a self-contained work page'},\n {id:'audit',effect:'RENDER_DIAGNOSTIC',label:'Check work product readiness'}\n]);\nfunction taskSteps(p){\n const title=safe(p.problem,105).replace(/[.?!]+$/,'')||'this project';\n const goal=safe(p.finish,90)||'one real, observable change';\n const practical=p.limit?('Respect constraint: '+safe(p.limit,95)+'.'):'Use only the resources already available.';\n const steps={\n  untangle:['Write down two facts about '+title+'.','Separate unanswered questions from confirmed facts.',\n    'Choose the smallest action possible in '+p.time+' minutes.','Record a real observation or obstacle.'],\n  make:['Name the intended user or purpose of '+title+'.','Make a first usable version, even if rough.',\n    'Check the result against: '+goal+'.','Save the result and one specific revision.'],\n  decide:['Write the first concrete option for '+title+'.','Write the second concrete option.',\n    'Compare time, reversibility, and downsides on the same criteria.','Choose a short trial and record its observed result.'],\n  debug:['Record what actually happens in '+title+'.','Record what you expected instead.',\n    'Change one reversible variable and run one test.','Write the observed result and how to undo the change.']\n };\n return [...steps[p.mode],practical];\n}\nfunction htmlSafe(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));}\nfunction csvCell(value){\n let v=String(value??'').replace(/[\\u0000-\\u001F]/g,' ');\n // Prevent spreadsheet-formula injection, including after whitespace.\n if(/^[\\s]*[=+@\\-]/.test(v))v=\"'\"+v;\n return '\"'+v.replace(/\"/g,'\"\"')+'\"';\n}\nfunction offerFeedback(message){\n $('jarvis-response').textContent=message;\n $('jarvis-response').classList.remove('hidden');\n notice(message.split('\\n')[0]);\n}\nfunction offerContext(){\n const p=active;\n const preferred={untangle:'a usable checklist',make:'a portable work page',decide:'a structured tracker',debug:'a readiness audit'};\n $('jarvis-context').textContent=p\n   ?'For \"'+safe(p.problem,110)+'\", I recommend '+preferred[p.mode]+'. All four actions below are executable in this file.'\n   :'Create or restore a working step in section 01–02. I will offer actions I can execute on that actual project.';\n}\nfunction runJarvis(id){\n if(!JARVIS_OFFERS.some(x=>x.id===id))throw Error('Unknown JAR;VIS capability');\n if(!active){offerFeedback('Nothing to work on yet. Start one project above; I cannot invent a real task for you.');return;}\n flush();\n const p=active,steps=taskSteps(p),stamp=when();\n if(id==='checklist'){\n  const list='\\n\\nJAR;VIS · EXECUTED CHECKLIST ('+stamp+')\\n'+\n    steps.map(x=>'- [ ] '+x).join('\\n')+'\\n';\n  if(p.note.length+list.length>12000){offerFeedback('Checklist not added: the working note is full. Export your note before reducing it.');return;}\n  p.note+=list;p.updated=stamp;persist();renderActive();\n  offerFeedback('DONE HERE: five checklist items were added to your editable working note. This did not complete those items.');\n }else if(id==='tracker'){\n  const rows=[['Project','Task','Status','Evidence','Date']];\n  steps.forEach((x,i)=>rows.push([p.problem,(i+1)+'. '+x,'Not started','','']));\n  const contents=rows.map(row=>row.map(csvCell).join(',')).join('\\r\\n')+'\\r\\n';\n  simpleFile('Lantern_JARVIS_Work_Tracker.csv',contents,'text/csv;charset=utf-8');\n  offerFeedback('FILE CREATED: Lantern_JARVIS_Work_Tracker.csv — five task rows and evidence columns. No other files were edited.');\n }else if(id==='page'){\n  const title=htmlSafe(safe(p.problem,140));\n  const items=steps.map(x=>'<li><label><input type=\"checkbox\"> '+htmlSafe(x)+'</label></li>').join('');\n  const note=htmlSafe(p.note);\n  const portable='<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">'+\n    '<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>'+title+' · Work Card</title>'+\n    '<style>body{max-width:780px;margin:24px auto;padding:18px;font:17px/1.6 system-ui;color:#192f29;background:#f7f7f1}h1{line-height:1.2}li{padding:9px 0}input[type=checkbox]{width:20px;height:20px;margin-right:9px}textarea{width:100%;box-sizing:border-box;min-height:200px;padding:12px;font:inherit}button{padding:10px 18px;border-radius:8px;background:#23463a;color:white;border:0}small{color:#476052}pre{white-space:pre-wrap;overflow-wrap:anywhere}section{border-top:1px solid #b5c9bc;margin-top:18px;padding-top:12px}@media print{button{display:none}}</style></head><body>'+\n    '<p><small>LANTERN · JAR;VIS LOCAL WORK CARD · no upload, no remote sync</small></p><h1>'+title+'</h1>'+\n    '<p><strong>Desired outcome:</strong> '+htmlSafe(p.finish||p.finishLine)+'</p>'+\n    '<p><strong>Constraint:</strong> '+htmlSafe(p.limit||'None recorded')+'</p>'+\n    '<section><h2>Five concrete steps</h2><ol>'+items+'</ol></section>'+\n    '<section><h2>Original working note</h2><pre>'+note+'</pre></section>'+\n    '<section><h2>My observations</h2><textarea placeholder=\"Write what actually changed here. This file never claims completion for you.\"></textarea></section>'+\n    '<button onclick=\"window.print()\">Print / Save to PDF</button> <small>Checkboxes and notes are not auto-saved. Print or save your results.</small></body></html>';\n  simpleFile('Lantern_JARVIS_Work_Card.html',portable,'text/html;charset=utf-8');\n  offerFeedback('FILE CREATED: Lantern_JARVIS_Work_Card.html — open it offline, check the steps, write observations, or print it. The work is not reported complete.');\n }else if(id==='audit'){\n  const reference=build(p.mode,p.problem,p.finish,p.limit,p.time).note;\n  const checks=[\n    [!!safe(p.problem),'A concrete problem is named.','Missing: name the actual task.'],\n    [!!safe(p.finish),'An explicit desired outcome is recorded.','Missing: one concrete desired outcome (not only a general intention).'],\n    [p.note.trim()!==reference.trim()&&p.note.trim().length>reference.trim().length/2,'The working note contains changes beyond its original scaffold.','The working note still resembles the untouched scaffold.'],\n    [!p.completed||!!safe(p.evidence),'Completion is either unclaimed or has a self-reported observation.','Completion is checked, but no observation or evidence was recorded.']\n  ];\n  const passed=checks.filter(x=>x[0]).length;\n  const issues=checks.filter(x=>!x[0]).map(x=>'- '+x[2]);\n  offerFeedback('JAR;VIS LOCAL AUDIT: '+passed+'/4 document checks passed.\\n'+\n    (issues.length?issues.join('\\n'):'No missing fields detected in this document.')+\n    '\\nThis is a structural check only; I did not inspect your local files or verify any outside action.');\n }\n}\n\n['checklist','tracker','page','audit'].forEach(id=>$('jarvis-'+id).addEventListener('click',()=>runJarvis(id)));\n$('build').addEventListener('click',()=>newProject(false));$('quick').addEventListener('click',()=>newProject(true));document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;applyMode();}));document.querySelectorAll('[data-min]').forEach(b=>b.addEventListener('click',()=>{minutes=+b.dataset.min;applyMinutes();}));\n[el.note,el.evidence].forEach(x=>x.addEventListener('input',()=>{clearTimeout(autosaveTimer);autosaveTimer=setTimeout(flush,180);}));el.completed.addEventListener('change',()=>{flush();renderActive();});$('save').addEventListener('click',save);$('fork').addEventListener('click',fork);\n$('copy').addEventListener('click',async()=>{if(!active)return;flush();const txt=plain(active);try{if(!navigator.clipboard)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(txt);notice('Working note copied.');}catch{el.note.focus();el.note.select();notice('Clipboard permission unavailable. Select and copy the working note manually.',true);}});\n$('download').addEventListener('click',()=>{if(!active)return;flush();simpleFile('Lantern_014_Working_Note.txt',plain(active),'text/plain;charset=utf-8');notice('Saved a working text file.');});$('print').addEventListener('click',()=>{if(!active)return;flush();window.print();});$('export-shelf').addEventListener('click',exportShelf);$('import-shelf').addEventListener('click',()=>$('import-file').click());$('import-file').addEventListener('change',e=>importShelf(e.target.files?.[0]));$('clear-shelf').addEventListener('click',()=>{if(!shelf.length)return;if(confirm('Clear all saved snapshots from this browser? This cannot be undone. Export a backup first if these matter.')){shelf=[];persist();renderShelf();notice('Saved local snapshots cleared; working copy left intact.');}});\nload();applyMode();applyMinutes();renderActive();renderShelf();offerContext();window.LANTERN014={status:()=>({mode,minutes,active:active?cleanProject(active):null,snapshots:shelf.length,storageAvailable}),offers:()=>JARVIS_OFFERS.map(x=>({...x})),executeOffer:runJarvis,version:'0.2.0'};\n})();\n</script>\n<script>\n\n(()=>{\n 'use strict';\n const ROOT='/functions/v1/jarvis-solo-live-017';\n const $=x=>document.getElementById(x);\n const allow=new Set(['jarvis','world','ghot','static_os']);\n let receipt=null,recorder=null,stream=null,chunks=[];\n const show=(id,s)=>$(id).textContent=String(s);\n function save(name,data,type){\n  const blob=data instanceof Blob?data:new Blob([data],{type}),url=URL.createObjectURL(blob);\n  const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();\n  setTimeout(()=>URL.revokeObjectURL(url),1500);\n }\n async function post(action,params){\n  const r=await fetch(ROOT+'/execute',{method:'POST',headers:{'content-type':'application/json'},\n   body:JSON.stringify(Object.assign({action},params)),cache:'no-store'});\n  const d=await r.json();if(!r.ok||!d.ok)throw Error(d.reason||'CONNECTED_ACTION_REFUSED');\n  return d;\n }\n async function connect(){\n  const b=$('connect-sources');b.disabled=true;show('connected-state','CHECKING PUBLIC GITHUB');\n  $('connected-offers').replaceChildren();show('connected-result','Reading actual public file identities…');\n  try{\n   const r=await fetch(ROOT+'/capabilities',{cache:'no-store'}),d=await r.json();\n   if(!r.ok||d.schema!=='jarvis.connected-capability-registry/v1')throw Error('REGISTRY_UNAVAILABLE');\n   let count=0;\n   for(const x of d.connected){\n    const card=document.createElement('div');card.className='offer';\n    const k=document.createElement('span');k.className='availability';k.textContent=x.state;\n    const h=document.createElement('strong');h.textContent=x.label;\n    const p=document.createElement('p');p.textContent=x.state==='CONNECTED_READ_ONLY'?\n     x.repo+' · '+x.ref+' · '+x.source_sha.slice(0,12):\n     'Source unavailable: '+(x.reason||'remote GitHub read failed');\n    const button=document.createElement('button');button.type='button';button.className='secondary';\n    button.textContent='Execute live source inspection →';\n    button.disabled=x.state!=='CONNECTED_READ_ONLY'||!allow.has(x.id);\n    if(!button.disabled){count++;button.onclick=()=>void inspect(x.id,button);}\n    card.append(k,h,p,button);$('connected-offers').append(card);\n   }\n   show('connected-state',count+' / '+d.connected.length+' VERIFIED · READ ONLY');\n   show('connected-result','Connected results are backed by actual GitHub file SHA values. Click one to compile a real downloadable report.');\n  }catch(e){show('connected-state','UNAVAILABLE · LOCAL STILL WORKS');\n   show('connected-result','Did not connect: '+(e.message||'unknown error'));}\n  finally{b.disabled=false;}\n }\n async function inspect(id,b){\n  if(!allow.has(id))return;b.disabled=true;\n  try{\n   const d=await post('source_report',{source:id});\n   if(d.performed!=='REMOTE_GITHUB_SOURCE_FETCH_AND_COMPILE'||d.writes!==0)\n    throw Error('NO_VERIFIED_SOURCE_RECEIPT');\n   save('JARVIS_Connected_'+id+'_Source_Report.json',JSON.stringify(d,null,2)+'\\n','application/json');\n   show('connected-result','EXECUTED: inspected real GitHub source '+d.report.github_source_blob_sha+' and created a JSON source report. GitHub writes: 0.');\n  }catch(e){show('connected-result','No source report created: '+e.message);}\n  finally{b.disabled=false;}\n }\n async function route(){\n  const b=$('connected-route'),p=$('connected-offer-text').value.trim();\n  $('connected-route-result').classList.remove('hidden');\n  if(!$('connected-consent').checked){show('connected-route-result','REFUSED: explicit consent required to send a short offer.');return;}\n  if(p.length<4||p.length>240){show('connected-route-result','Enter 4–240 characters first.');return;}\n  b.disabled=true;show('connected-route-result','Executing source-owned JAR;VIS router…');\n  try{\n   const d=await post('route_offer',{offer:p});\n   if(d.schema!=='jarvis.remote-live-offer-receipt/v1'||d.writes!==0||d.action_executed_on_person_or_device)\n     throw Error('UNVERIFIED_ROUTER_RECEIPT');\n   receipt=d;\n   const choices=d.plan.actions.slice(0,4).map((x,i)=>(i+1)+'. '+x.label+' → '+x.effect).join('\\n');\n   show('connected-route-result','ACTUAL JAR;VIS ENGINE EXECUTED\\nDetected: '+d.plan.intent.kind+' / '+d.plan.intent.when+\n    '\\n'+choices+'\\n\\nPROPOSALS ONLY. A recording is not made until you press Start below.');\n   $('connected-receipt').classList.remove('hidden');\n  }catch(e){receipt=null;$('connected-receipt').classList.add('hidden');\n    show('connected-route-result','No successful router execution: '+e.message);}\n  finally{b.disabled=false;}\n }\n async function start(){\n  if(recorder)return;\n  $('audio-start').disabled=true;\n  try{\n   if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('BROWSER_NO_RECORDER');\n   stream=await navigator.mediaDevices.getUserMedia({audio:true});\n   const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(x=>MediaRecorder.isTypeSupported(x));\n   chunks=[];recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);\n   recorder.ondataavailable=e=>{if(e.data?.size)chunks.push(e.data);};\n   recorder.onstop=()=>{\n    const blob=new Blob(chunks,{type:recorder?.mimeType||'audio/webm'});\n    if(blob.size){\n     const ext=blob.type.includes('mp4')?'m4a':'webm';\n     save('JARVIS_Real_Recording_'+new Date().toISOString().replace(/[:.]/g,'-')+'.'+ext,blob,blob.type);\n     show('audio-status','Recorded and downloaded '+blob.size+' bytes. No upload or sharing.');\n    }else show('audio-status','No audio bytes received. No recording claimed.');\n    stream?.getTracks().forEach(t=>t.stop());\n    stream=null;recorder=null;chunks=[];$('audio-start').disabled=false;$('audio-stop').disabled=true;\n   };\n   recorder.start(700);$('audio-stop').disabled=false;\n   show('audio-status','Recording locally. Press Stop to save the real audio file.');\n  }catch(e){stream?.getTracks().forEach(t=>t.stop());stream=null;recorder=null;\n   $('audio-start').disabled=false;show('audio-status','No recording started: '+e.message);}\n }\n $('connect-sources').addEventListener('click',()=>void connect());\n $('connected-route').addEventListener('click',()=>void route());\n $('connected-receipt').addEventListener('click',()=>{if(receipt)save('JARVIS_Live_Routing_Receipt.json',JSON.stringify(receipt,null,2)+'\\n','application/json');});\n $('audio-start').addEventListener('click',()=>void start());\n $('audio-stop').addEventListener('click',()=>{if(recorder?.state==='recording')recorder.stop();});\n if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){\n  $('audio-start').disabled=true;show('audio-status','This browser cannot record audio; connected source inspection still works.');\n }\n window.JARVIS015={connect,route,get lastReceipt(){return receipt},version:'0.1.0',githubAuthority:'READ_ONLY'};\n})();\n\n</script>\n</body>\n</html>";
